// Records VEGAS Pro 18 wrote, kept in Reno (vegtemplates.cpp, generated by tests/vegas/maketemplates.py from sample
// projects), for the .veg writer to start from when the project being saved has none of a kind.
#pragma once
#include <cstdint>
#include <string>
#include <vector>

namespace reno {
namespace veg {

// Bytes of a template chunk (24-byte header included), or of the whole template project ("project").
// Empty if there is no such template. Names: project, videoTrack, audioTrack, fx, panCrop, mediaAV, mediaVideo,
// mediaAudio, mediaVeg, mediaSubclip, mediaGenerated, eventAudioChain, trackAudioChain, trackEnvelopes,
// eventEnvelopes, marker, group, bus.
std::string templateBytes(const char* name);

// VST plug-ins the sample projects use, as VEGAS names them (the 16 bytes of the CLSID).
struct KnownVst {
    uint32_t vstId;
    const char* name;
    unsigned char clsid[16];
};
const std::vector<KnownVst>& knownVsts();

}  // namespace veg
}  // namespace reno
